package lockfile

import (
	"bufio"
	"context"
	"regexp"
	"strings"

	"github.com/aquasecurity/trivy/pkg/dependency"
	"github.com/aquasecurity/trivy/pkg/dependency/parser/utils"
	ftypes "github.com/aquasecurity/trivy/pkg/fanal/types"
	xio "github.com/aquasecurity/trivy/pkg/x/io"
)

// androidTestConfigurationRegexp matches test configurations generated by the
// Android Gradle Plugin. Unlike JVM projects, Android names test configurations
// after the build variant, e.g. "debugUnitTestRuntimeClasspath" or
// "freeReleaseAndroidTestCompileClasspath", so they don't start with "test".
// The match is anchored to the whole name and requires a non-empty variant
// prefix so that production configurations are never matched.
var androidTestConfigurationRegexp = regexp.MustCompile(`^.+(UnitTest|AndroidTest)(CompileClasspath|RuntimeClasspath|AnnotationProcessorClasspath)$`)

// isTestConfiguration reports whether the given Gradle configuration is a test
// configuration. JVM test configurations start with "test" (e.g.
// "testCompileClasspath"), while Android test configurations embed the build
// variant (see androidTestConfigurationRegexp).
func isTestConfiguration(configuration string) bool {
	if configuration == "" {
		return false
	}
	return strings.HasPrefix(configuration, "test") || androidTestConfigurationRegexp.MatchString(configuration)
}

type Parser struct{}

func NewParser() *Parser {
	return &Parser{}
}

func (Parser) Parse(_ context.Context, r xio.ReadSeekerAt) ([]ftypes.Package, []ftypes.Dependency, error) {
	var pkgs []ftypes.Package
	scanner := bufio.NewScanner(r)
	var lineNum int
	for scanner.Scan() {
		lineNum++
		line := strings.TrimSpace(scanner.Text())
		if strings.HasPrefix(line, "#") { // skip comments
			continue
		}

		// dependency format: group:artifact:version=classPaths
		dep := strings.Split(line, ":")
		if len(dep) != 3 { // skip the last line with lists of empty configurations
			continue
		}

		name := strings.Join(dep[:2], ":")
		version, classPathsString, _ := strings.Cut(dep[2], "=")

		dev := true

		for classPath := range strings.SplitSeq(classPathsString, ",") {
			if !isTestConfiguration(classPath) {
				dev = false
				break
			}
		}

		pkgs = append(pkgs, ftypes.Package{
			ID:      dependency.ID(ftypes.Gradle, name, version),
			Name:    name,
			Version: version,
			Dev:     dev,
			Locations: []ftypes.Location{
				{
					StartLine: lineNum,
					EndLine:   lineNum,
				},
			},
			Relationship: ftypes.RelationshipUnknown,
		})

	}
	return utils.UniquePackages(pkgs), nil, nil
}
